IF OBJECT_ID(N'dbo.products',N'U') IS NULL CREATE TABLE dbo.products(id INT IDENTITY(1,1) PRIMARY KEY, data NVARCHAR(MAX) NOT NULL CHECK(ISJSON(data)=1));
GO
IF OBJECT_ID(N'dbo.customers',N'U') IS NULL CREATE TABLE dbo.customers(id INT IDENTITY(1,1) PRIMARY KEY, data NVARCHAR(MAX) NOT NULL CHECK(ISJSON(data)=1));
GO
IF OBJECT_ID(N'dbo.vendors',N'U') IS NULL CREATE TABLE dbo.vendors(id INT IDENTITY(1,1) PRIMARY KEY, data NVARCHAR(MAX) NOT NULL CHECK(ISJSON(data)=1));
GO
IF OBJECT_ID(N'dbo.documents',N'U') IS NULL BEGIN CREATE TABLE dbo.documents(id INT IDENTITY(1,1) PRIMARY KEY, kind VARCHAR(20) NOT NULL, date VARCHAR(10) NOT NULL, data NVARCHAR(MAX) NOT NULL CHECK(ISJSON(data)=1)); CREATE INDEX document_kind_date ON dbo.documents(kind,date); END;
GO
IF OBJECT_ID(N'dbo.movements',N'U') IS NULL BEGIN CREATE TABLE dbo.movements(id INT IDENTITY(1,1) PRIMARY KEY, productId INT NOT NULL REFERENCES dbo.products(id), date VARCHAR(10) NOT NULL, quantity FLOAT NOT NULL, reason NVARCHAR(255) NOT NULL); CREATE INDEX movement_date ON dbo.movements(date); END;
GO
IF OBJECT_ID(N'dbo.users',N'U') IS NULL CREATE TABLE dbo.users(id INT IDENTITY(1,1) PRIMARY KEY, name NVARCHAR(120) NOT NULL, email NVARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role NVARCHAR(60) NOT NULL, permissions NVARCHAR(MAX) NOT NULL CHECK(ISJSON(permissions)=1));
GO
IF OBJECT_ID(N'dbo.sessions',N'U') IS NULL BEGIN CREATE TABLE dbo.sessions(token VARCHAR(64) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, userId INT NOT NULL REFERENCES dbo.users(id), expires BIGINT NOT NULL, duration BIGINT NOT NULL DEFAULT 86400000); CREATE INDEX session_expiry ON dbo.sessions(expires); END;
GO
IF OBJECT_ID(N'dbo.audit',N'U') IS NULL CREATE TABLE dbo.audit(id INT IDENTITY(1,1) PRIMARY KEY, date VARCHAR(40), actor NVARCHAR(120), action NVARCHAR(255), details NVARCHAR(MAX));
GO
IF OBJECT_ID(N'dbo.settings',N'U') IS NULL CREATE TABLE dbo.settings(id INT PRIMARY KEY CHECK(id=1), data NVARCHAR(MAX) NOT NULL CHECK(ISJSON(data)=1));
